export const professionalReferenceSheets = [{"sourceFile":"в ЦЭФ по SAQ/статьи КоАП УКСБУ.xlsx","sourceSheetName":"Штрафы","entries":[{"number":1,"description":"Привлечение к административной ответственности по часть 1 ст.184 КоАП (Несвоевременное предоставление или непредоставление, а равно предоставление недостоверной информации по форме, установленной уполномоченным органом в области оценочной деятельности)"},{"number":2,"description":"Привлечение к административной ответственности по ст.185 КоАП (Нарушение обязанности сохранения коммерческой, банковской тайны, сведений кредитных отчетов или информации из базы данных кредитных историй кредитного бюро)"},{"number":3,"description":"Привлечение к административной ответственности по ст.214 КоАП (Нарушение законодательства Республики Казахстан о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма)"},{"number":4,"description":"Привлечение к административной ответственности по часть 2 ст.230 КоАП (несвоевременное предоставление или непредоставление информации ГПО)."},{"number":5,"description":"Привлечение к административной ответственности по ст.239 КоАП (представления заведомо недостоверной финансовой отчетности, отказа от представления финансовой отчетности, представления с нарушением установленного срока либо непредставления ее без уважительной причины учредителям (участникам) организаций в соответствии с учредительными документами, уполномоченному органу в области государственной статистики по месту регистрации, органам государственного контроля и надзора в соответствии с их компетенцией, в депозитарий финансовой отчетности)"},{"number":6,"description":"Привлечение к административной ответственности по часть 5 ст.239 КоАП (Непредставление, несвоевременное представление отчетности о своей деятельности в уполномоченный орган аккредитованными профессиональными организациями бухгалтеров и (или) организациями по профессиональной сертификации бухгалтеров в установленном законодательством Республики Казахстан порядке)"},{"number":7,"description":"Привлечение к административной ответственности по ст.239-1 КоАП (Нарушение порядка проведения экзаменов организациями по профессиональной сертификации бухгалтеров)"},{"number":8,"description":"Привлечение к административной ответственности по ст.240 КоАП (Разглашение тайны бухгалтерской информации)"},{"number":9,"description":"Привлечение к административной ответственности по ст.241 КоАП (Нарушение правил аккредитации, установленных законодательством Республики Казахстан о бухгалтерском учете и финансовой отчетности)"},{"number":10,"description":"Привлечение к административной ответственности по ст.245 КоАП (Сокрытие аудитором факта нарушения законодательства Республики Казахстан о бухгалтерском учете и финансовой отчетности от заказчиков проведения аудита)"},{"number":11,"description":"Привлечение к административной ответственности по ст.246 КоАП (Составление аудитором и аудиторской организацией недостоверного аудиторского отчета, а также недостоверного аудиторского заключения по налогам)"},{"number":12,"description":"Привлечение к административной ответственности по ст.246-1 КоАП (Нарушение аудиторской организацией порядка проведения аудита по налогам, аудита специального назначения субъектов квазигосударственного сектора)"},{"number":13,"description":"Привлечение к административной ответственности по часть 3 ст.247 КоАП (Проведение аудита в запрещенных Законом Республики Казахстан \"Об аудиторской деятельности\" случаях)"},{"number":14,"description":"Привлечение к административной ответственности по часть 5 ст.247 КоАП (Несвоевременное предоставление или непредоставление, а равно предоставление недостоверных сведений аккредитованными профессиональными аудиторскими организациями в соответствующие уполномоченные органы, информации, предоставление которой требуется в соответствии с законодательством Республики Казахстан об аудиторской деятельности)"},{"number":15,"description":"Привлечение к административной ответственности по часть 7 ст.247 КоАП (Несвоевременное предоставление или непредоставление аудиторскими организациями отчетности в уполномоченный орган в соответствии с квалификационными требованиями и (или) информации по страхованию своей гражданско-правовой ответственности по форме, утвержденной уполномоченным органом)"},{"number":16,"description":"Привлечение к административной ответственности по часть 10 ст.247 КоАП (Проведение обязательного аудита аудиторской организацией, не соответствующей минимальным требованиям к аудиторским организациям, которые проводят обязательный аудит)"},{"number":17,"description":"Привлечение к административной ответственности по часть 11 ст.247 КоАП (Невступление и (или) несвоевременное вступление аудиторской организации в профессиональную аудиторскую организацию в сроки, предусмотренные Законом Республики Казахстан \"Об аудиторской деятельности\")"},{"number":18,"description":"Привлечение к административной ответственности по ст.248 КоАП (Нарушения, связанные с использованием и хранением личной печати аудитора)"},{"number":19,"description":"Привлечение к административной ответственности по ст.249 КоАП (Предоставление аудируемым субъектом несвоевременной, недостоверной или неполной информации аудиторской организации)"},{"number":20,"description":"Привлечение к административной ответственности по ст.250 КоАП (Уклонение от проведения обязательного аудита либо препятствование его проведению)"},{"number":21,"description":"Привлечение к административной ответственности по часть 3 ст.462 КоАП (Невыполнение или ненадлежащее выполнение законных требований или предписаний, представлений, постановлений, выданных органами государственного контроля и надзора (должностных лиц), должностными лицами государственных органов в пределах их компетенции, за исключением случаев, предусмотренных статьями 162 и 227 настоящего Кодекса)"},{"number":22,"description":"Привлечение к административной ответственности по ст.464 КоАП (Нарушение норм лицензирования)"}]}];
